{
  "root": "main_stack",
  "state": {
    "productSales": [
      {
        "product": "A",
        "totalQuantity": 180
      },
      {
        "product": "B",
        "totalQuantity": 150
      },
      {
        "product": "C",
        "totalQuantity": 120
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg"
      },
      "children": [
        "sales_perf_section",
        "quantity_breakdown_section"
      ]
    },
    "sales_perf_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "sales_perf_header",
        "sales_perf_text"
      ]
    },
    "sales_perf_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "sales_perf_icon",
        "sales_perf_title"
      ]
    },
    "sales_perf_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000465_01_1_bar-chart.svg"
      },
      "children": []
    },
    "sales_perf_title": {
      "type": "Text",
      "props": {
        "text": "Product Sales Performance",
        "variant": "h2"
      },
      "children": []
    },
    "sales_perf_text": {
      "type": "Text",
      "props": {
        "text": "This analysis summarizes the total quantity sold for each product based on the provided sales data. Product A leads in total sales quantity."
      },
      "children": []
    },
    "quantity_breakdown_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "quantity_breakdown_header",
        "quantity_intro_text",
        "sales_table",
        "summary_text"
      ]
    },
    "quantity_breakdown_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "quantity_breakdown_icon",
        "quantity_breakdown_title"
      ]
    },
    "quantity_breakdown_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000465_01_2_graph-up.svg"
      },
      "children": []
    },
    "quantity_breakdown_title": {
      "type": "Text",
      "props": {
        "text": "Quantity Sold Breakdown",
        "variant": "h2"
      },
      "children": []
    },
    "quantity_intro_text": {
      "type": "Text",
      "props": {
        "text": "The following table details the total quantity sold for each product:"
      },
      "children": []
    },
    "sales_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "product",
            "label": "Product"
          },
          {
            "key": "totalQuantity",
            "label": "Total Quantity"
          }
        ],
        "statePath": "/productSales",
        "domain": "generic",
        "preferredPresentation": "table",
        "numericColumns": [
          "totalQuantity"
        ]
      },
      "children": []
    },
    "summary_text": {
      "type": "Text",
      "props": {
        "text": "Product A has the highest total quantity sold with 180 units."
      },
      "children": []
    }
  }
}
